class ListNode:
    def __init__(self, val, nxt=None):
        self.val = val
        self.next = nxt

def build(values):
    # Python list -> linked nodes, built from the tail so each node points forward.
    head = None
    for val in reversed(values):
        head = ListNode(val, head)
    return head

def to_list(head):
    # Linked nodes -> Python list, head to tail.
    values = []
    while head is not None:
        values.append(head.val)
        head = head.next
    return values

def solution(head, n):
    # For each node, count the nodes from it to the end: O(L^2).
    dummy = ListNode(0, build(head))
    before = dummy
    while before.next is not None:
        count = 0
        node = before.next
        while node is not None:
            count += 1
            node = node.next
        if count == n:                  # before.next is n-th from the end
            before.next = before.next.next
            break
        before = before.next
    return to_list(dummy.next)
